72	
73	/**
74	 * @author Vitaliy Fedoriv
75	 */
76	
77	@RestController
78	@CrossOrigin(exposedHeaders = "errors, content-type")
79	@RequestMapping("/api")
80	public class OwnerRestControllerV1 implements OwnersApi {
81	
82	    /** Maximum number of owners a single city may contain; creating an owner in a city that
83	     *  already has this many owners is rejected with 409 Conflict. */
84	    private static final int MAX_OWNERS_PER_CITY = 50;
85	
86	    /** When the owner's city already contains at least this many owners (but fewer than
87	     *  {@link #MAX_OWNERS_PER_CITY}, so the create is still allowed), the new owner's
88	     *  'capacityWarning' flag is set true to signal the city is approaching its capacity limit;
89	     *  otherwise it is false. */
90	    private static final int CAPACITY_WARNING_THRESHOLD = 40;
91	
92	    /** Maximum number of owners that may be created on a single day (by registration date); creating
93	     *  an owner once this many owners already carry today's registration date is rejected with
94	     *  429 Too Many Requests. */
95	    private static final int MAX_OWNERS_PER_DAY = 100;
96	
97	    /** When more than this many owners already carry today's registration date at creation time, the
98	     *  new owner's 'bulkSignupWarning' flag is set true; otherwise it is false. */
99	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
100	
101	    /** Disposable email domains that are not accepted for an owner; a create whose email domain is on
102	     *  this blocklist is rejected with 400 Bad Request. Compared case-insensitively (lower-cased). */
103	    private static final Set<String> DISPOSABLE_EMAIL_DOMAINS =
104	        Set.of("mailinator.com", "tempmail.com", "guerrillamail.com");
105	
106	    /** Dedicated audit logger; a line is emitted here for each successful owner create. */
107	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
108	
109	    /** Serializes the immutable structured audit event emitted alongside the audit line. */
110	    private static final ObjectMapper AUDIT_EVENT_MAPPER = JsonMapper.builder().build();
111	
112	    /** Monotonically increasing sequence stamped on each structured {@code OWNER_CREATED} event,
113	     *  shared across all creates so the events carry a strict global order. */
114	    private static final AtomicLong OWNER_CREATED_SEQUENCE = new AtomicLong();
115	
116	    private final ClinicService clinicService;
117	
118	    private final OwnerMapper ownerMapper;
119	
120	    private final PetMapper petMapper;
121	
122	    private final VisitMapper visitMapper;
123	
124	    private final TelephoneNormalizer telephoneNormalizer;
125	
126	    private final HouseholdNormalizer householdNormalizer;
127	
128	    private final AddressNormalizer addressNormalizer;
129	
130	    private final EmailNormalizer emailNormalizer;
131	
132	    /**
133	     * Records the owner created for each already-seen {@code Idempotency-Key}, so a create that
134	     * repeats with the same key returns the originally created owner (200) instead of creating a
135	     * duplicate. Keyed by the header value; concurrent because creates may be handled on any thread.
136	     */
137	    private final java.util.concurrent.ConcurrentMap<String, OwnerDto> idempotentCreates =
138	        new java.util.concurrent.ConcurrentHashMap<>();
139	
140	    public OwnerRestControllerV1(ClinicService clinicService,
141	                                 OwnerMapper ownerMapper,
142	                                 PetMapper petMapper,
143	                                 VisitMapper visitMapper,
144	                                 TelephoneNormalizer telephoneNormalizer,
145	                                 HouseholdNormalizer householdNormalizer,
146	                                 AddressNormalizer addressNormalizer,
147	                                 EmailNormalizer emailNormalizer) {
148	        this.clinicService = clinicService;
149	        this.ownerMapper = ownerMapper;
150	        this.petMapper = petMapper;
151	        this.visitMapper = visitMapper;
152	        this.telephoneNormalizer = telephoneNormalizer;
153	        this.householdNormalizer = householdNormalizer;
154	        this.addressNormalizer = addressNormalizer;
155	        this.emailNormalizer = emailNormalizer;
156	    }
157	
158	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
159	    @Override
160	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
161	        Collection<Owner> owners;
162	        if (lastName != null) {
163	            owners = this.clinicService.findOwnerByLastName(lastName);
164	        } else {
165	            owners = this.clinicService.findAllOwners();
166	        }
167	        if (owners.isEmpty()) {
168	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
169	        }
170	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
171	    }
172	
173	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
174	    @Override
175	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
176	        Owner owner = this.clinicService.findOwnerById(ownerId);
177	        if (owner == null) {
178	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
179	        }
180	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
181	    }
182	
183	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
184	    @Override
185	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
186	        // Idempotent create: when the request carries an 'Idempotency-Key' header that has already
187	        // been used for a successful create, return the originally created owner with 200 OK instead
188	        // of running the create pipeline again (which would otherwise reject the repeat as a duplicate
189	        // with 409). A first, unseen key runs the normal create and records its result under the key.
190	        String idempotencyKey = currentIdempotencyKey();
191	        if (idempotencyKey == null || idempotencyKey.isBlank()) {
192	            return createOwner(ownerFieldsDto);
193	        }
194	        OwnerDto previouslyCreated = idempotentCreates.get(idempotencyKey);
195	        if (previouslyCreated != null) {
196	            return new ResponseEntity<>(previouslyCreated, HttpStatus.OK);
197	        }
198	        ResponseEntity<OwnerDto> response = createOwner(ownerFieldsDto);
199	        idempotentCreates.put(idempotencyKey, response.getBody());
200	        return response;
201	    }
202	
203	    /**
204	     * Returns the value of the current request's {@code Idempotency-Key} header, or {@code null} when
205	     * the request carries no such header (or there is no active servlet request). Reading it from the
206	     * request context here keeps the header — a request-level concern surrounding the create — out of
207	     * the generated {@link #addOwner} signature and the {@link #createOwner} pipeline.
208	     *
209	     * @return the {@code Idempotency-Key} header value, or {@code null} when absent
210	     */
211	    private String currentIdempotencyKey() {
212	        RequestAttributes attributes = RequestContextHolder.getRequestAttributes();
213	        if (attributes instanceof ServletRequestAttributes servletAttributes) {
214	            return servletAttributes.getRequest().getHeader("Idempotency-Key");
215	        }
216	        return null;
217	    }
218	
219	    /**
220	     * Runs the full owner-creation pipeline for a create request and returns the 201 Created
221	     * response for the newly persisted owner: the request fields are mapped and normalized, every
222	     * create-time policy (per-day and per-city quota, household membership, identity duplicate and
223	     * soft-duplicate) is applied in order, the create-time derived fields are assigned, the owner is
224	     * saved and audited, and a {@code Location} header for the new owner is set. Keeping the pipeline
225	     * in its own method leaves {@link #addOwner} as the thin request entry point, so request-level
226	     * concerns that merely surround a create (rather than being one of its steps) can be layered in
227	     * {@code addOwner} without disturbing the creation steps gathered here.
228	     *
229	     * @param ownerFieldsDto the submitted owner fields
230	     * @return a 201 Created response carrying the persisted owner and its {@code Location} header
231	     */
232	    private ResponseEntity<OwnerDto> createOwner(OwnerFieldsDto ownerFieldsDto) {
233	        HttpHeaders headers = new HttpHeaders();
234	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
235	        normalizeOwnerFields(owner);
236	        // Enforce the pre-persistence policies that can reject the new owner outright.
237	        rejectDisallowedOwnerCreation(owner);
238	        // Resolve the owner's household membership: assign the deterministic 'householdId' (a pure
239	        // function of last name and postcode), cap the membership level for a new household member,
240	        // and record the household size. The household id is no longer part of the identity key, so
241	        // this no longer rejects a household duplicate: owners sharing a household are distinguished
242	        // by the identity-key check below and otherwise flagged as soft duplicates.
243	        boolean declaredHouseholdMember =
244	            applyHouseholdMembership(owner, Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold()));
245	        // Reject the create when the owner's whole derived identity key (the SHA-256 over normalized
246	        // telephone, lower-cased email and the Soundex of the last name) already matches an existing
247	        // owner. This single rule subsumes the former separate telephone, email and household
248	        // duplicate checks.
249	        rejectWhenIdentityInUse(owner);
250	        // Flag the owner as a possible (soft) duplicate when, although not a hard duplicate, it
251	        // shares an existing owner's last name and postcode with a different telephone. A declared
252	        // household member is never flagged: it is a known member, not a suspected duplicate.
253	        assignPossibleDuplicate(owner, declaredHouseholdMember);
254	        // Assign the remaining create-time derived fields (namesake count, customer code,
255	        // membership number and bulk-signup warning), each fixed at creation time.
256	        assignDerivedFields(owner);
257	        // Assign the (household-capped) membership level, fixed at creation time. This runs after the
258	        // derived fields above because the level is computed from the membership points, which depend
259	        // on the namesake count assigned in assignDerivedFields.
260	        assignMembershipLevel(owner);
261	        this.clinicService.saveOwner(owner);
262	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
263	        // Record the successful create on the dedicated AUDIT log.
264	        auditOwnerCreated(owner, ownerDto);
265	        headers.setLocation(UriComponentsBuilder.newInstance()
266	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
267	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
268	    }
269	
270	    /**
271	     * Emits the audit line recording a successful owner create on the dedicated {@code AUDIT} log,
272	     * carrying the owner id, its current primary identifier (see {@link #primaryIdentifier}), the
273	     * registration date, membership level and membership number so the create can be traced. Keeping
274	     * the audit emission in its own helper leaves {@link #createOwner} a thin pipeline and gives the
275	     * create's audit side-effects a single home, so a further audit side-effect of a create is added
276	     * here (or as a sibling helper) rather than inline in the pipeline.
277	     *
278	     * @param owner    the persisted owner
279	     * @param ownerDto the mapped view of the persisted owner, source of the membership fields
280	     */
281	    private void auditOwnerCreated(Owner owner, OwnerDto ownerDto) {
282	        AUDIT.info("Owner created: id={} customerCode={} registrationDate={} membershipLevel={} membershipNumber={}",
283	            owner.getId(), primaryIdentifier(owner), owner.getRegistrationDate(),
284	            ownerDto.getMembershipLevel(), ownerDto.getMembershipNumber());
285	        auditOwnerCreatedEvent(owner, ownerDto);
286	    }
287	
288	    /**
289	     * Emits the immutable structured {@code OWNER_CREATED} event on the {@code AUDIT} log as a JSON
290	     * object {@code {seq, ownerId, customerCode, membershipLevel, event}}. The {@code seq} is a
291	     * strictly increasing integer across every create (see {@link #OWNER_CREATED_SEQUENCE}), giving
292	     * the events a total order. The identifier field carries the owner's current primary identifier
293	     * (see {@link #primaryIdentifier}) — the customer code today, and whatever replaces it later — so
294	     * unifying the customer code into a member id makes the event carry the member id by changing only
295	     * {@link #primaryIdentifier}.
296	     *
297	     * @param owner    the persisted owner
298	     * @param ownerDto the mapped view of the persisted owner, source of the membership level
299	     */
300	    private void auditOwnerCreatedEvent(Owner owner, OwnerDto ownerDto) {
301	        OwnerCreatedEvent event = new OwnerCreatedEvent(
302	            OWNER_CREATED_SEQUENCE.incrementAndGet(), owner.getId(), primaryIdentifier(owner),
303	            ownerDto.getMembershipLevel(), "OWNER_CREATED");
304	        AUDIT.info(AUDIT_EVENT_MAPPER.writeValueAsString(event));
305	    }
306	
307	    /**
308	     * The immutable structured audit event published for a successful owner create. Its
309	     * {@code customerCode} field carries the owner's current primary identifier (see
310	     * {@link #primaryIdentifier}), so the same event shape follows the identifier as it changes.
311	     */
312	    private record OwnerCreatedEvent(long seq, Integer ownerId, String customerCode,
313	        Integer membershipLevel, String event) {
314	    }
315	
316	    /**
317	     * Returns the owner's current primary identifier: the single value that identifies the owner in
318	     * the audit trail and in any audit side-effect of a create. This is the customer code today;
319	     * resolving it through one accessor means that if the primary identifier is later changed (for
320	     * example, the customer code being unified into a member id) every audit consumer follows the new
321	     * identifier by changing only this method.
322	     *
323	     * @param owner the owner whose primary identifier is required
324	     * @return the owner's current primary identifier
325	     */
326	    private String primaryIdentifier(Owner owner) {
327	        return owner.getCustomerCode();
328	    }
329	
330	    /**
331	     * Enforces the pre-persistence policies that reject a newly mapped and normalized owner
332	     * outright, in order, before any derived fields are assigned or the owner is saved. Each
333	     * independent rule lives in its own {@code rejectWhen...} guard and is applied here in order, so
334	     * the sequence of create-time rejections stays readable and a new rule is added as one more
335	     * guard. Grouping the rules here keeps {@link #addOwner} focused on the household, derived-field
336	     * and persistence steps. The single duplicate rule that rejects an owner whose whole identity
337	     * key matches an existing one is applied separately in {@link #rejectWhenIdentityInUse}.
338	     *
339	     * @param owner the newly mapped and normalized owner being created
340	     */
341	    private void rejectDisallowedOwnerCreation(Owner owner) {
342	        rejectWhenDailyLimitReached(owner);
343	        rejectWhenCityAtCapacity(owner);
344	    }
345	
346	    /**
347	     * Applies the household-membership rules for a newly normalized owner being created. The
348	     * household id is a deterministic function of the owner's last name and postcode, so owners
349	     * with the same last name and postcode share it automatically; it is assigned to the new owner
350	     * here. Because the household is keyed on (last name, postcode), any existing owner with the
351	     * same last name and postcode is a member of the same household. A new owner may join an
352	     * existing household: rather than the create being rejected, the newcomer's membership level is
353	     * capped at one above the household's current maximum (see {@link #assignMembershipLevel}). When
354	     * the request declares it shares the household via {@code sharesHousehold} the owner is a known,
355	     * declared member and is never flagged as a possible duplicate. The owner's
356	     * {@code householdSize} (the number of owners sharing the household after this create) is
357	     * recorded either way.
358	     *
359	     * @param owner           the newly mapped and normalized owner being created
360	     * @param sharesHousehold whether the request declared that the owner shares an existing household
361	     * @return {@code true} if the owner joined an existing household as a declared member
362	     */
363	    private boolean applyHouseholdMembership(Owner owner, boolean sharesHousehold) {
364	        // Assign the deterministic household id (a pure function of last name and postcode) so every
365	        // owner with the same last name and postcode shares it automatically.
366	        owner.setHouseholdId(householdNormalizer.householdId(owner.getLastName(), owner.getPostcode()));
367	        // Identify any existing owners in the same household (same computed household id). A new owner
368	        // may join an existing household: its membership level is capped at one above the household's
369	        // current maximum (see assignMembershipLevel) rather than the create being rejected outright.
370	        List<Owner> householdMembers = sameHouseholdOwners(owner);
371	        // An owner that joins an existing household while the request declares it shares that
372	        // household is a known, declared member and so is never flagged as a possible duplicate.
373	        boolean declaredHouseholdMember = !householdMembers.isEmpty() && sharesHousehold;
374	        // Record the size of this owner's household after this create, fixed at creation time.
375	        owner.setHouseholdSize(householdMembers.size() + 1);
376	        return declaredHouseholdMember;
377	    }
378	
379	    /**
380	     * Assigns the create-time derived fields of a newly normalized owner whose household membership
381	     * has already been resolved: the namesake count, the per-city customer code, the membership
382	     * number derived from that customer code and the registration fiscal year, the bulk-signup warning
383	     * flag and the city capacity warning flag. Each value is fixed at creation time and is
384	     * independent of the others. Grouping them
385	     * here keeps {@link #addOwner} focused on the high-level create sequence.
386	     *
387	     * @param owner the owner being created, already normalized and with its household resolved
388	     */
389	    private void assignDerivedFields(Owner owner) {
390	        // Record how many existing owners already share this owner's first and last name
391	        // (compared case-insensitively) before this create, fixed at creation time.
392	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
393	        // Assign the customer code '<REGION>-<HASH8>' from the region derived from the postcode
394	        // and an 8-hex-character hash of the normalized telephone and last name, fixed at creation
395	        // time.
396	        owner.setCustomerCode(customerCode(owner));
397	        // Assign the membership number '<customerCode>-M<YY>', where YY is the last two digits
398	        // of the fiscal year of the registration date (e.g. 'NSW-A1B2C3D4-M26'), fixed at
399	        // creation time.
400	        owner.setMembershipNumber(membershipNumber(owner.getCustomerCode(), owner.getRegistrationDate()));
401	        // Flag the create when more than 80 owners have already been created on this owner's
402	        // (adjusted business-day) registration date, fixed at creation time.
403	        owner.setBulkSignupWarning(
404	            countOwnersRegisteredOn(owner.getRegistrationDate()) > BULK_SIGNUP_WARNING_THRESHOLD);
405	        // Flag the create when the owner's city is approaching its capacity limit: it already holds
406	        // between CAPACITY_WARNING_THRESHOLD and MAX_OWNERS_PER_CITY - 1 owners (40-49). A city at or
407	        // over the limit is rejected earlier (see rejectWhenCityAtCapacity), so this is never reached
408	        // for a full city. Fixed at creation time.
409	        int cityOwners = countOwnersInCity(owner.getCity());
410	        owner.setCapacityWarning(
411	            cityOwners >= CAPACITY_WARNING_THRESHOLD && cityOwners < MAX_OWNERS_PER_CITY);
412	    }
413	
414	    /**
415	     * Assigns the new owner's membership level, capped by their household, and fixes it at creation
416	     * time. The level a newly created owner would earn from their membership points cannot exceed
417	     * one above the current maximum membership level among their existing household members (the
418	     * owners already sharing this owner's household id); the capped value is stored so it is returned
419	     * unchanged on later reads. When the owner has no existing household member no cap applies and
420	     * the plain points-derived level is used.
421	     *
422	     * @param owner the owner being created, already normalized and with its derived fields assigned
423	     */
424	    private void assignMembershipLevel(Owner owner) {
425	        int level = ownerMapper.membershipLevel(ownerMapper.membershipPoints(owner));
426	        List<Owner> householdMembers = sameHouseholdOwners(owner);
427	        if (!householdMembers.isEmpty()) {
428	            int maxMemberLevel = householdMembers.stream()
429	                .mapToInt(this::memberLevel)
430	                .max()
431	                .getAsInt();
432	            level = Math.min(level, maxMemberLevel + 1);
433	        }
434	        owner.setMembershipLevel(level);
435	    }
436	
437	    /**
438	     * Returns an existing household member's membership level for the purpose of capping a new
439	     * member's level: the level stored on the member when present (the already-capped value fixed at
440	     * its own creation), otherwise the level derived from its membership points (for members created
441	     * before the level was persisted).
442	     *
443	     * @param member an existing owner in the same household
444	     * @return the member's membership level
445	     */
446	    private int memberLevel(Owner member) {
447	        return member.getMembershipLevel() != null
448	            ? member.getMembershipLevel()
449	            : ownerMapper.membershipLevel(ownerMapper.membershipPoints(member));
450	    }
451	
452	    /**
453	     * Rejects creating an owner whose whole derived identity key already matches an existing owner,
454	     * with 409 Conflict. The identity key ({@link Owner#getIdentityKey()}) is the SHA-256 hex over
455	     * the normalized telephone, the lower-cased email (or empty) and the Soundex of the last name, so
456	     * this single rule replaces the former separate telephone, email and household duplicate checks:
457	     * two owners collide only when their whole keys are equal, and members of one household with
458	     * different telephones have different keys and are both allowed (instead flagged as soft
459	     * duplicates).
460	     *
461	     * @param owner the owner being created, already normalized
462	     */
463	    private void rejectWhenIdentityInUse(Owner owner) {
464	        String identityKey = owner.getIdentityKey();
465	        boolean inUse = existingOwners()
466	            .anyMatch(existing -> identityKey.equals(existing.getIdentityKey()));
467	        if (inUse) {
468	            throw new DuplicateIdentityException(
469	                "An owner with identity key " + identityKey + " already exists");
470	        }
471	    }
472	
473	    /**
474	     * Assigns the soft-duplicate flags for a newly normalized owner that has already passed the hard
475	     * duplicate (identity-key) check. When an existing owner has a different identity key but shares
476	     * this owner's postcode and the Soundex code of its last name, the new owner is still created but
477	     * flagged as a possible duplicate: {@code possibleDuplicate} is set true and
478	     * {@code possibleDuplicateOf} to the matching owner's id (the lowest such id when several match).
479	     * Otherwise {@code possibleDuplicate} is false and {@code possibleDuplicateOf} is left absent.
480	     * A postcode is required on both sides for a match, so an owner without a postcode is never a
481	     * possible duplicate. A declared household member is never flagged: it is a known member of the
482	     * household, not a suspected duplicate. Both values are fixed at creation time.
483	     *
484	     * @param owner                   the owner being created, already normalized and confirmed not a
485	     *                                hard duplicate
486	     * @param declaredHouseholdMember whether the owner joined an existing household as a declared
487	     *                                member
488	     */
489	    private void assignPossibleDuplicate(Owner owner, boolean declaredHouseholdMember) {
490	        Integer matchId = declaredHouseholdMember || owner.getPostcode() == null ? null : existingOwners()
491	            .filter(existing -> isPossibleDuplicateOf(existing, owner))
492	            .map(Owner::getId)
493	            .min(Integer::compareTo)
494	            .orElse(null);
495	        owner.setPossibleDuplicate(matchId != null);
496	        owner.setPossibleDuplicateOf(matchId);
497	    }
498	
499	    /**
500	     * Tests whether an existing owner makes the owner being created a possible (soft) duplicate: the
501	     * two have different identity keys (an equal key would already have been rejected as a hard
502	     * duplicate) but share a postcode (required on both sides, so an owner without a postcode never
503	     * matches) and the Soundex code of their last name. A match flags the new owner as a possible
504	     * duplicate of the existing one without rejecting the create.
505	     *
506	     * @param existing an existing owner to compare against
507	     * @param owner    the owner being created
508	     * @return {@code true} if the existing owner makes the new owner a possible duplicate
509	     */
510	    private boolean isPossibleDuplicateOf(Owner existing, Owner owner) {
511	        return existing.getPostcode() != null
512	            && existing.getPostcode().equals(owner.getPostcode())
513	            && Soundex.encode(existing.getLastName()).equals(Soundex.encode(owner.getLastName()))
514	            && !existing.getIdentityKey().equals(owner.getIdentityKey());
515	    }
516	
517	    /**
518	     * Rejects creating an owner once {@link #MAX_OWNERS_PER_DAY} or more owners already carry this
519	     * owner's adjusted business-day registration date, with 429 Too Many Requests.
520	     *
521	     * @param owner the owner being created
522	     */
523	    private void rejectWhenDailyLimitReached(Owner owner) {
524	        if (countOwnersRegisteredOn(owner.getRegistrationDate()) >= MAX_OWNERS_PER_DAY) {
525	            throw new DailyOwnerLimitExceededException(
526	                "The maximum number of owners that may be created today has already been reached");
527	        }
528	    }
529	
530	    /**
531	     * Rejects creating an owner when the owner's city already contains {@link #MAX_OWNERS_PER_CITY}
532	     * or more owners, with 409 Conflict.
533	     *
534	     * @param owner the owner being created
535	     */
536	    private void rejectWhenCityAtCapacity(Owner owner) {
537	        if (countOwnersInCity(owner.getCity()) >= MAX_OWNERS_PER_CITY) {
538	            throw new CityCapacityExceededException(
539	                "The city " + owner.getCity() + " already contains the maximum number of owners");
540	        }
541	    }
542	
543	    /**
544	     * Canonicalizes the fields of a newly mapped owner on create, in place, so each value is
545	     * persisted and returned in its canonical form. The address is normalized (trimmed, whitespace
546	     * collapsed, upper-cased and common abbreviations expanded, rejecting a value blank after
547	     * normalization with 400), the telephone is normalized to E.164 (rejecting an unformattable
548	     * value with 400), the email is lower-cased, and a missing registration date defaults to the
549	     * server's current date. Canonicalising the address here, before the household checks read it,
550	     * ensures duplicate detection and the shared household id both compare the normalized form.
551	     * Centralising these per-field canonicalizations here keeps {@link #addOwner} focused on the
552	     * duplicate, household and customer-code rules.
553	     *
554	     * @param owner the newly mapped owner to canonicalize
555	     */
556	    private void normalizeOwnerFields(Owner owner) {
557	        // Canonicalize the owner's address fields on create so the address is stored and returned in
558	        // canonical form and every later comparison (household duplicate detection and the shared
559	        // household id) uses it. A value that is blank after normalization is rejected with 400.
560	        normalizeAddressFields(owner);
561	        // Normalize the telephone on create so it is stored and returned in canonical E.164 form.
562	        // A value that cannot form a valid E.164 number, or whose national-number length is wrong
563	        // for its country code (+61 => 9 national digits, +1 => 10), is rejected with 400.
564	        owner.setTelephone(telephoneNormalizer.normalizeAndValidate(owner.getTelephone()));
565	        // Store the (already syntactically validated) email lower-cased so it is persisted and
566	        // returned in canonical form. A missing email is left untouched.
567	        owner.setEmail(emailNormalizer.normalize(owner.getEmail()));
568	        // Reject an email whose domain is on the disposable-domain blocklist with 400, after
569	        // canonicalization so the comparison sees the lower-cased value.
570	        rejectDisposableEmailDomain(owner.getEmail());
571	        // Validate the optional postcode against the fixed range for the city's region. A postcode
572	        // is checked only when present (it is optional); one out of range for the city's region is
573	        // rejected with 400. A city with no known region accepts any 4-digit postcode. The stored
574	        // value is left unchanged.
575	        PostcodeValidator.validate(owner.getCity(), owner.getPostcode());
576	        // Reject a supplied registration date that is later than the server's current date with
577	        // 400, before any defaulting or business-day adjustment, so a future date is never
578	        // persisted regardless of how the roll-forward would move it.
579	        rejectFutureRegistrationDate(owner.getRegistrationDate());
580	        // Default the registration date to the server's current date when the client did not
581	        // supply one, then roll the effective date forward to a business day so a Saturday or
582	        // Sunday (whether supplied or defaulted) becomes the following Monday. The adjusted date
583	        // is persisted and returned in ISO 'YYYY-MM-DD' form and is the value every registration-
584	        // date-derived field (such as the membership number's year segment) and the per-day
585	        // create-limit are computed from.
586	        java.time.LocalDate effectiveDate = owner.getRegistrationDate() == null
587	            ? java.time.LocalDate.now() : owner.getRegistrationDate();
588	        owner.setRegistrationDate(toBusinessDay(effectiveDate));
589	    }
590	
591	    /**
592	     * Canonicalizes a newly mapped owner's address on create, in place, so it is persisted and
593	     * returned in canonical form. The owner may supply its address in either of two forms and the
594	     * structured form is preferred when present: when a non-blank {@code addressLine1} is supplied it
595	     * (and the optional {@code addressLine2}) is normalized (trimmed, whitespace collapsed, upper-cased
596	     * and common street-type abbreviations expanded) via {@link AddressNormalizer}, otherwise the flat
597	     * {@code address} input is normalized for backward compatibility. Whichever form is supplied, the
598	     * stored {@code address} is composed from the normalized structured lines when present — the
599	     * normalized {@code addressLine1} with a single space and the normalized {@code addressLine2}
600	     * appended when an {@code addressLine2} is present — or the normalized flat address otherwise. An
601	     * owner that supplies no address in either form is rejected with 400. Canonicalising the address
602	     * here, before the household checks read it, ensures duplicate detection and the shared household
603	     * id both compare the normalized form. Isolating the address concern in its own helper keeps
604	     * {@link #normalizeOwnerFields} focused on sequencing the per-field canonicalizations.
605	     *
606	     * @param owner the newly mapped owner whose address is canonicalized
607	     */
608	    private void normalizeAddressFields(Owner owner) {
609	        if (owner.getAddressLine1() != null && !owner.getAddressLine1().isBlank()) {
610	            String line1 = addressNormalizer.normalize(owner.getAddressLine1());
611	            owner.setAddressLine1(line1);
612	            String composed = line1;
613	            if (owner.getAddressLine2() != null && !owner.getAddressLine2().isBlank()) {
614	                String line2 = addressNormalizer.normalize(owner.getAddressLine2());
615	                owner.setAddressLine2(line2);
616	                composed = line1 + " " + line2;
617	            }
618	            owner.setAddress(composed);
619	        }
620	        else {
621	            owner.setAddress(addressNormalizer.normalize(owner.getAddress()));
622	        }
623	    }
624	
625	    /**
626	     * Rejects a supplied email whose domain is on the disposable-domain blocklist
627	     * ({@link #DISPOSABLE_EMAIL_DOMAINS}) with a 400 Bad Request. The email is already canonicalized
628	     * (lower-cased) here, so the domain — the part after the final {@code '@'} — is compared directly
629	     * against the lower-cased blocklist. A {@code null} email (email is optional) or one without a
630	     * domain part is left untouched.
631	     *
632	     * @param email the owner's canonicalized email, or {@code null} when absent
633	     */
634	    private void rejectDisposableEmailDomain(String email) {
635	        if (email == null) {
636	            return;
637	        }
638	        int at = email.lastIndexOf('@');
639	        if (at < 0) {
640	            return;
641	        }
642	        String domain = email.substring(at + 1).toLowerCase(Locale.ROOT);
643	        if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
644	            throw new DisposableEmailException(
645	                "The supplied email domain " + domain + " is on the disposable-domain blocklist");
646	        }
647	    }
648	
649	    /**
650	     * Rejects a supplied registration date that is later than the server's current date with a
651	     * 400 Bad Request. A missing registration date (defaulted to the server date later) is
652	     * accepted, and a date on or before today is left for the normal defaulting and business-day
653	     * adjustment.
654	     *
655	     * @param registrationDate the client-supplied registration date, or {@code null} when absent
656	     */
657	    private void rejectFutureRegistrationDate(java.time.LocalDate registrationDate) {
658	        if (registrationDate != null && registrationDate.isAfter(java.time.LocalDate.now())) {
659	            throw new InvalidRegistrationDateException(
660	                "The supplied registration date " + registrationDate + " is later than the current date");
661	        }
662	    }
663	
664	    /**
665	     * The fixed list of public holidays. A registration date that lands on one of these dates is
666	     * rolled forward to the next non-holiday business day, in addition to the weekend rule.
667	     */
668	    private static final java.util.Set<java.time.LocalDate> PUBLIC_HOLIDAYS = java.util.Set.of(
669	        java.time.LocalDate.of(2026, 1, 1),
670	        java.time.LocalDate.of(2026, 1, 26),
671	        java.time.LocalDate.of(2026, 4, 25),
672	        java.time.LocalDate.of(2026, 12, 25),
673	        java.time.LocalDate.of(2026, 12, 28));
674	
675	    /**
676	     * Rolls a registration date forward to a business day: a Saturday, Sunday or listed public
677	     * holiday advances to the next non-holiday weekday, while an ordinary weekday is returned
678	     * unchanged. Applied to the effective registration date (whether supplied in the request or
679	     * defaulted to the server date) so the persisted registration date, every value derived from it
680	     * and the per-day create-limit all use the adjusted business day.
681	     *
682	     * @param date the effective registration date
683	     * @return the same date if it is a non-holiday weekday, otherwise the next non-holiday business day
684	     */
685	    private java.time.LocalDate toBusinessDay(java.time.LocalDate date) {
686	        java.time.LocalDate adjusted = date;
687	        while (adjusted.getDayOfWeek() == java.time.DayOfWeek.SATURDAY
688	            || adjusted.getDayOfWeek() == java.time.DayOfWeek.SUNDAY
689	            || PUBLIC_HOLIDAYS.contains(adjusted)) {
690	            adjusted = adjusted.plusDays(1);
691	        }
692	        return adjusted;
693	    }
694	
695	    /**
696	     * Builds the customer code '<REGION>-<HASH8>' for a newly created owner, where REGION is the
697	     * region derived from the owner's postcode (falling back to the city, via
698	     * {@link LocalityResolver}) and HASH8 is the first 8 upper-case hex characters of the SHA-256
699	     * digest over the owner's normalized telephone concatenated with the last name (e.g.
700	     * 'NSW-A1B2C3D4'). When that base code already belongs to an existing owner, '-<n>' is appended
701	     * with the smallest n of 2 or more that makes it unique, so distinct owners always receive
702	     * distinct customer codes.
703	     *
704	     * @param owner the owner being created, already normalized
705	     * @return the formatted, de-duplicated customer code
706	     */
707	    private String customerCode(Owner owner) {
708	        String region = LocalityResolver.resolve(owner.getCity(), owner.getPostcode());
709	        String hash8 = Sha256Hex.upperHexPrefix(owner.getTelephone() + owner.getLastName(), 8);
710	        String base = CustomerCode.format(region, hash8);
711	        return deduplicateCode(base, existingCustomerCodes());
712	    }
713	
714	    /**
715	     * Collects the customer codes already assigned to existing owners, the set a newly built code is
716	     * de-duplicated against. Gathering them here keeps {@link #customerCode} focused on building the
717	     * code and lets the uniqueness step (see {@link #deduplicateCode}) work against the codes alone.
718	     *
719	     * @return the customer codes currently in use
720	     */
721	    private Set<String> existingCustomerCodes() {
722	        return existingOwners()
723	            .map(Owner::getCustomerCode)
724	            .filter(code -> code != null)
725	            .collect(Collectors.toSet());
726	    }
727	
728	    /**
729	     * Returns a unique code for a newly built base identifier: the base itself when it is not already
730	     * taken, otherwise the base with {@code "-<n>"} appended, using the smallest {@code n} of 2 or
731	     * more that makes it unique. Keeping the collision rule in its own helper leaves the identifier's
732	     * construction to its builder and gives the "make it unique" step a single home independent of
733	     * which identifier is being assigned.
734	     *
735	     * @param base  the freshly built identifier, before any uniqueness suffix
736	     * @param taken the identifiers already in use
737	     * @return {@code base} when unused, otherwise the smallest {@code base + "-" + n} not in {@code taken}
738	     */
739	    private String deduplicateCode(String base, Set<String> taken) {
740	        if (!taken.contains(base)) {
741	            return base;
742	        }
743	        int n = 2;
744	        while (taken.contains(base + "-" + n)) {
745	            n++;
746	        }
747	        return base + "-" + n;
748	    }
749	
750	    /**
751	     * Streams the existing owners that the create-time rules match a new owner against. Every
752	     * duplicate, quota and derived-field rule scans this same set of owners and differs only in the
753	     * predicate it applies, so fetching them is centralized here to keep each rule focused on its
754	     * own matching criterion rather than on how the existing owners are retrieved.
755	     *
756	     * @return a stream over all existing owners
757	     */
758	    private Stream<Owner> existingOwners() {
759	        // Exclude soft-deleted owners: a deleted owner is retained for reads but must not block a
760	        // new create, so the duplicate, identity and household checks (and the other create-time
761	        // scans built on this helper) ignore it.
762	        return this.clinicService.findAllOwners().stream()
763	            .filter(existing -> !Boolean.TRUE.equals(existing.getDeleted()));
764	    }
765	
766	    /**
767	     * Counts the existing owners located in the given city, compared case-insensitively. Used to
768	     * fix the per-city sequence of an owner's customer code at creation time.
769	     *
770	     * @param city the city of the owner being created
771	     * @return the number of existing owners in a matching city
772	     */
773	    private int countOwnersInCity(String city) {
774	        return (int) existingOwners()
775	            .filter(existing -> existing.getCity() != null
776	                && existing.getCity().equalsIgnoreCase(city))
777	            .count();
778	    }
779	
780	    /**
781	     * Counts the existing owners whose registration date is the given adjusted business day. Used
782	     * to enforce the per-day cap that rejects creating an owner once {@link #MAX_OWNERS_PER_DAY}
783	     * owners already carry that business day as their registration date.
784	     *
785	     * @param date the adjusted business-day registration date to match
786	     * @return the number of existing owners registered on that date
787	     */
788	    private int countOwnersRegisteredOn(java.time.LocalDate date) {
789	        return (int) existingOwners()
790	            .filter(existing -> date.equals(existing.getRegistrationDate()))
791	            .count();
792	    }
793	
794	    /**
795	     * Builds the membership number '<customerCode>-M<YY>' for a newly created owner, where YY is
796	     * the last two digits of the fiscal year of the (business-day-adjusted) registration date
797	     * (e.g. 'NSW-A1B2C3D4-M26'). The fiscal year starts on 1 July, so a registration date on or
798	     * after 1 July carries the following calendar year's fiscal year.
799	     *
800	     * @param customerCode     the owner's customer code
801	     * @param registrationDate the owner's registration date
802	     * @return the formatted membership number
803	     */
804	    private String membershipNumber(String customerCode, java.time.LocalDate registrationDate) {
805	        return String.format("%s-M%02d",
806	            customerCode, org.springframework.samples.petclinic.util.FiscalYear.of(registrationDate) % 100);
807	    }
808	
809	    /**
810	     * Returns the existing owners in the given owner's household, i.e. those sharing its
811	     * deterministic household id (the same last name and postcode). The id is computed via
812	     * {@link HouseholdNormalizer} so that last names differing only in letter case or in incidental
813	     * whitespace are treated as the same household. Centralising how "the same household" is matched
814	     * here keeps that definition in one place for every caller.
815	     *
816	     * @param owner the owner being created, with its household id already assigned
817	     * @return the existing owners in the owner's household (possibly empty)
818	     */
819	    private List<Owner> sameHouseholdOwners(Owner owner) {
820	        String householdId = owner.getHouseholdId();
821	        return existingOwners()
822	            .filter(existing -> householdId.equals(
823	                householdNormalizer.householdId(existing.getLastName(), existing.getPostcode())))
824	            .toList();
825	    }
826	
827	    /**
828	     * Counts the existing owners who share the given first and last name, compared
829	     * case-insensitively. Used to fix an owner's namesake count at creation time.
830	     *
831	     * @param firstName the first name of the owner being created
832	     * @param lastName  the last name of the owner being created
833	     * @return the number of existing owners with a matching first and last name
834	     */
835	    private int countNamesakes(String firstName, String lastName) {
836	        return (int) existingOwners()
837	            .filter(existing -> existing.getFirstName() != null
838	                && existing.getFirstName().equalsIgnoreCase(firstName)
839	                && existing.getLastName() != null
840	                && existing.getLastName().equalsIgnoreCase(lastName))
841	            .count();
842	    }
843	
844	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
845	    @Override
846	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
847	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
848	        if (currentOwner == null) {
849	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
850	        }
851	        currentOwner.setAddress(ownerFieldsDto.getAddress());
852	        currentOwner.setCity(ownerFieldsDto.getCity());
853	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
854	        currentOwner.setLastName(ownerFieldsDto.getLastName());
855	        // Normalize the telephone to canonical E.164 form so it is stored and returned
856	        // consistently with create; an unformattable value is rejected with 400.
857	        currentOwner.setTelephone(telephoneNormalizer.normalize(ownerFieldsDto.getTelephone()));
858	        currentOwner.setEmail(emailNormalizer.normalize(ownerFieldsDto.getEmail()));
859	        this.clinicService.saveOwner(currentOwner);
860	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
861	    }
862	
863	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
864	    @Transactional
865	    @Override
866	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
867	        Owner owner = this.clinicService.findOwnerById(ownerId);
868	        if (owner == null) {
869	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
870	        }
871	        // Soft-delete: flag the owner as deleted and retain the row rather than removing it, so the
872	        // owner is still returned by GET (with 'deleted' true) and only excluded from the create-time
873	        // duplicate and identity checks (see existingOwners()).
874	        owner.setDeleted(true);
875	        this.clinicService.saveOwner(owner);
876	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
877	    }
878	
879	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
880	    @Override
881	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
882	        Owner owner = this.clinicService.findOwnerById(ownerId);
883	        if (owner == null) {
884	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
885	        }
886	        HttpHeaders headers = new HttpHeaders();
887	        Pet pet = petMapper.toPet(petFieldsDto);
888	        owner.setId(ownerId);
889	        pet.setOwner(owner);
890	        pet.getType().setName(null);
891	        this.clinicService.savePet(pet);
892	        PetDto petDto = petMapper.toPetDto(pet);
893	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
894	            .buildAndExpand(pet.getId()).toUri());
895	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
896	    }
897	
898	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
899	    @Override
900	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
901	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
902	        if (currentOwner != null) {
903	            Pet currentPet = this.clinicService.findPetById(petId);
904	            if (currentPet != null) {
905	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
906	                currentPet.setName(petFieldsDto.getName());
907	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
908	                this.clinicService.savePet(currentPet);
909	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
910	            }
911	        }
912	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
913	    }
914	
915	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
916	    @Override
917	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
918	        HttpHeaders headers = new HttpHeaders();
919	        Visit visit = visitMapper.toVisit(visitFieldsDto);
920	        Pet pet = new Pet();
921	        pet.setId(petId);
922	        visit.setPet(pet);
923	        this.clinicService.saveVisit(visit);
924	        VisitDto visitDto = visitMapper.toVisitDto(visit);
925	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
926	            .buildAndExpand(visit.getId()).toUri());
927	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
928	    }
929	
930	
931	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
932	    @Override
933	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
934	        Owner owner = this.clinicService.findOwnerById(ownerId);
935	        if (owner != null) {
936	            Pet pet = owner.getPet(petId);
937	            if (pet != null) {
938	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
939	            }
940	        }
941	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
942	    }
943	}
